{
  "obligations": [
    {
      "statement": "Licensed recruitment agencies must not charge migrant workers placement fees.",
      "type": "prohibition",
      "exceptions": [],
      "effective_date": "2026-10-01",
      "evidence": [
        {
          "doc_id": "REG-2026-0417",
          "doc_kind": "regulation",
          "source_sha256": "6571084f3ff2215fcf48d467c7d9e8afd808f5f4b644c00ddca7a9ca66e4c5d9",
          "page": 3,
          "quote": "No licensed recruitment agency shall charge a migrant worker any placement fee; permissible costs are limited to those defined in §4(b)."
        },
        {
          "doc_id": "REG-2026-0417",
          "doc_kind": "regulation",
          "source_sha256": "6571084f3ff2215fcf48d467c7d9e8afd808f5f4b644c00ddca7a9ca66e4c5d9",
          "page": 3,
          "quote": "The provisions in Part II take effect on 1 October 2026."
        }
      ]
    },
    {
      "statement": "Licensed recruitment agencies must reissue the published fee schedule within 30 days after issue.",
      "type": "requirement",
      "exceptions": [],
      "effective_date": "2026-10-01",
      "evidence": [
        {
          "doc_id": "REG-2026-0417",
          "doc_kind": "regulation",
          "source_sha256": "6571084f3ff2215fcf48d467c7d9e8afd808f5f4b644c00ddca7a9ca66e4c5d9",
          "page": 3,
          "quote": "Each licensed recruitment agency must reissue its published fee schedule within 30 days after this amendment is issued. The reissued schedule must identify the BDT 0 worker-paid placement fee limit and distinguish employer-paid costs."
        },
        {
          "doc_id": "REG-2026-0417",
          "doc_kind": "regulation",
          "source_sha256": "6571084f3ff2215fcf48d467c7d9e8afd808f5f4b644c00ddca7a9ca66e4c5d9",
          "page": 3,
          "quote": "The provisions in Part II take effect on 1 October 2026."
        }
      ]
    },
    {
      "statement": "Employer-paid medical examination costs remain permissible when no cost is transferred to the worker.",
      "type": "exception",
      "exceptions": [],
      "effective_date": "2026-10-01",
      "evidence": [
        {
          "doc_id": "REG-2026-0417",
          "doc_kind": "regulation",
          "source_sha256": "6571084f3ff2215fcf48d467c7d9e8afd808f5f4b644c00ddca7a9ca66e4c5d9",
          "page": 3,
          "quote": "Employer-paid medical examination costs remain permissible under this amended synthetic rule when no amount is transferred to, deducted from, or reclaimed from the worker."
        },
        {
          "doc_id": "REG-2026-0417",
          "doc_kind": "regulation",
          "source_sha256": "6571084f3ff2215fcf48d467c7d9e8afd808f5f4b644c00ddca7a9ca66e4c5d9",
          "page": 3,
          "quote": "The provisions in Part II take effect on 1 October 2026."
        }
      ]
    }
  ]
}
